from abc import ABCMeta, abstractmethod
from future.utils import with_metaclass


class LifetimePolicy(with_metaclass(ABCMeta)):
    @abstractmethod
    def should_be_removed(self):
        pass

    def should_be_called(self):
        return True

    def callback_called(self):
        pass


class Forever(LifetimePolicy):
    def should_be_removed(self):
        return False


class NCalls(LifetimePolicy):
    def __init__(self, expected_call_number=1):
        self.call_counter = expected_call_number

    def should_be_removed(self):
        return self.call_counter == 0

    def callback_called(self):
        if self.call_counter > 0:
            self.call_counter -= 1


class OneTimeCall(NCalls):
    def __init__(self):
        super(OneTimeCall, self).__init__(expected_call_number=1)


class WhenCounterHitsN(LifetimePolicy):
    def __init__(self, counter=1, target=1):
        self.counter = counter
        self.target = target

    def should_be_called(self):
        return self.counter == self.target

    def should_be_removed(self):
        return self.counter < self.target

    def callback_called(self):
        self.counter -= 1
